1	// pattern: Imperative Shell
2	//
3	// The pds's first *outbound* iroh leg. Everything else in `iroh_tunnel.rs` accepts; this
4	// dials. It reuses that same bound `Endpoint` — an iroh endpoint both accepts and dials, so
5	// the instance presents one stable node identity to the relay, which is exactly the identity
6	// the relay authorizes against (`connection.remote_id()`; no credential ever travels in a
7	// message).
8	//
9	// Framing mirrors the relay's accept side: one JSON request per bidirectional stream,
10	// delimited by our FIN, one JSON response back, under a per-stream deadline.
11	//
12	// Connections are lazy and cached. A relay that is down must never become a pds outage, so
13	// every failure here is logged and swallowed by the caller (`crate::notifications`), never
14	// propagated into a request path.
15	
16	use std::sync::Arc;
17	use std::time::Duration;
18	
19	use iroh::{Endpoint, EndpointAddr, EndpointId};
20	use notify_relay::protocol::{Request, Response, ALPN, MAX_MESSAGE_LEN};
21	use tokio::sync::Mutex;
22	
23	/// Maximum time for one request/response exchange, matching the relay's own stream deadline.
24	const STREAM_TIMEOUT: Duration = Duration::from_secs(30);
25	
26	/// How long a dial may take before we give up and let the next send retry.
27	const DIAL_TIMEOUT: Duration = Duration::from_secs(15);
28	
29	/// A dialing client for one configured relay.
30	pub struct NotifyRelayClient {
31	    endpoint: Endpoint,
32	    /// Where to dial. Built from the configured node id alone, so reaching the relay depends
33	    /// on iroh discovery + holepunching rather than on the operator knowing an address —
34	    /// which is the point of naming a relay by node id in the first place.
35	    relay_addr: EndpointAddr,
36	    /// The claim code from `[notifications] enrollment_code`, presented on every `enroll`.
37	    /// The relay consumes it once; later enrolls of an already-enrolled node succeed anyway,
38	    /// so re-presenting a spent code is harmless.
39	    enrollment_code: Option<String>,
40	    /// The live connection, if any. Behind an async mutex because establishing one is an
41	    /// `await`: without serializing, a burst of sends after a relay restart would each dial
42	    /// their own connection.
43	    connection: Mutex<Option<iroh::endpoint::Connection>>,
44	}
45	
46	impl NotifyRelayClient {
47	    /// Build a client for `relay_node_id`, dialing from the pds's own endpoint.
48	    ///
49	    /// Fails only if the configured node id is unparseable — a config error worth surfacing
50	    /// at startup rather than as a silent non-delivery later.
51	    pub fn new(
52	        endpoint: Endpoint,
53	        relay_node_id: &str,
54	        enrollment_code: Option<String>,
55	    ) -> anyhow::Result<Self> {
56	        let relay_id: EndpointId = relay_node_id
57	            .parse()
58	            .map_err(|e| anyhow::anyhow!("notifications.relay is not a valid iroh node id: {e}"))?;
59	        Ok(Self::with_addr(
60	            endpoint,
61	            EndpointAddr::new(relay_id),
62	            enrollment_code,
63	        ))
64	    }
65	
66	    /// Build a client for a relay at a known address, skipping discovery.
67	    ///
68	    /// The loopback end-to-end test dials a relay bound on 127.0.0.1 with iroh's `Minimal`
69	    /// preset, which has no discovery to resolve a bare node id against.
70	    pub fn with_addr(
71	        endpoint: Endpoint,
72	        relay_addr: EndpointAddr,
73	        enrollment_code: Option<String>,
74	    ) -> Self {
75	        Self {
76	            endpoint,
77	            relay_addr,
78	            enrollment_code,
79	            connection: Mutex::new(None),
80	        }
81	    }
82	
83	    /// Send one request and await its response, dialing (and enrolling) as needed.
84	    pub async fn call(&self, request: Request) -> anyhow::Result<Response> {
85	        let response = self.exchange(request.clone()).await?;
86	
87	        // Enrollment is not a startup step: the relay may have been restarted, re-provisioned,
88	        // or reached for the first time mid-run. Rather than tracking enrollment state we let
89	        // the relay tell us, and enroll exactly when it says we must. This is idempotent and
90	        // costs one extra round trip only on the first send after a relay forgets us.
91	        if matches!(response, Response::NotEnrolled) && !matches!(request, Request::Enroll { .. }) {
92	            let enrolled = self
93	                .exchange(Request::Enroll {
94	                    claim_code: self.enrollment_code.clone(),
95	                })
96	                .await?;
97	            if !matches!(enrolled, Response::Ok) {
98	                anyhow::bail!("relay refused enrollment: {enrolled:?}");
99	            }
100	            return self.exchange(request).await;
101	        }
102	
103	        Ok(response)
104	    }
105	
106	    /// One request/response exchange on a fresh stream over the cached connection.
107	    async fn exchange(&self, request: Request) -> anyhow::Result<Response> {
108	        let encoded = serde_json::to_vec(&request)?;
109	
110	        // One retry, because the failure we expect is a *stale* cached connection: the relay
111	        // restarted and our handle to it is dead, which only surfaces when we try to use it.
112	        // Retrying with a fresh dial turns that into a transparent reconnect. A second failure
113	        // is a real outage, and the caller drops the notification.
114	        let mut last_error = None;
115	        for attempt in 0..2 {
116	            let connection = match self.connect(attempt == 1).await {
117	                Ok(c) => c,
118	                Err(e) => {
119	                    last_error = Some(e);
120	                    continue;
121	                }
122	            };
123	            match Self::round_trip(&connection, &encoded).await {
124	                Ok(response) => return Ok(response),
125	                Err(e) => {
126	                    tracing::debug!(error = %e, attempt, "notify relay exchange failed");
127	                    // Drop the connection so the next attempt re-dials rather than reusing
128	                    // something we just proved broken.
129	                    *self.connection.lock().await = None;
130	                    last_error = Some(e);
131	                }
132	            }
133	        }
134	        Err(last_error.unwrap_or_else(|| anyhow::anyhow!("notify relay unreachable")))
135	    }
136	
137	    /// Return the cached connection, dialing a new one if absent (or if `force_redial`).
138	    async fn connect(&self, force_redial: bool) -> anyhow::Result<iroh::endpoint::Connection> {
139	        let mut guard = self.connection.lock().await;
140	        if force_redial {
141	            *guard = None;
142	        }
143	        if let Some(connection) = guard.as_ref() {
144	            return Ok(connection.clone());
145	        }
146	        let connection = tokio::time::timeout(
147	            DIAL_TIMEOUT,
148	            self.endpoint.connect(self.relay_addr.clone(), ALPN),
149	        )
150	        .await
151	        .map_err(|_| anyhow::anyhow!("dialing the notify relay timed out"))?
152	        .map_err(|e| anyhow::anyhow!("failed to dial the notify relay: {e}"))?;
153	        *guard = Some(connection.clone());
154	        Ok(connection)
155	    }
156	
157	    async fn round_trip(
158	        connection: &iroh::endpoint::Connection,
159	        encoded: &[u8],
160	    ) -> anyhow::Result<Response> {
161	        let exchange = async {
162	            let (mut send, mut recv) = connection.open_bi().await?;
163	            send.write_all(encoded).await?;
164	            // FIN is the frame delimiter: the relay reads to end, so without this it waits
165	            // forever and we time out against a perfectly healthy relay.
166	            send.finish()?;
167	            let bytes = recv.read_to_end(MAX_MESSAGE_LEN).await?;
168	            Ok::<Response, anyhow::Error>(serde_json::from_slice(&bytes)?)
169	        };
170	        tokio::time::timeout(STREAM_TIMEOUT, exchange)
171	            .await
172	            .map_err(|_| anyhow::anyhow!("notify relay exchange timed out"))?
173	    }
174	}
