176	// ── The send worker ───────────────────────────────────────────────────────────
177	//
178	// Triggers must never wait on the relay: a claim ceremony that hangs because a push relay is
179	// slow has traded a missed banner for a broken request. So callers hand work to an unbounded
180	// in-process queue and return immediately.
181	//
182	// The queue is in-memory only, deliberately. A missed push is a missed *banner*, not lost
183	// data — the app reconciles state from Custos on next contact — so durable queuing would add
184	// a table, a sweep, and a retry policy to protect something that is already recoverable.
185	
186	/// One unit of work for the relay worker.
187	#[derive(Debug)]
188	pub enum NotifyJob {
189	    /// Register (or re-register) a device's APNs token, recording the handle we get back.
190	    RegisterHandle {
191	        owner: RegistrationOwner,
192	        apns_token: String,
193	        apns_topic: String,
194	    },
195	    /// Forget a handle at the relay. Best effort: a handle we fail to drop expires with the
196	    /// device token rather than lingering forever.
197	    DropHandle { handle: String },
198	    /// Deliver one sealed payload.
199	    Push {
200	        owner: RegistrationOwner,
201	        handle: String,
202	        kid: i64,
203	        enc: String,
204	        ct: String,
205	    },
206	}
207	
208	/// Which registration table a job's row lives in — the two surfaces are keyed differently, so
209	/// the worker needs to know which one to write a handle back to (or prune on a dead token).
210	#[derive(Debug, Clone, PartialEq, Eq)]
211	pub enum RegistrationOwner {
212	    /// A wallet account's device: `(did, device_uuid)`.
213	    Account { did: String, device_uuid: String },
214	    /// An admin-companion device, keyed by `admin_devices.id`.
215	    AdminDevice { admin_device_id: String },
216	}
217	
218	/// The sender half handed to trigger sites. Cloning is cheap; dropping every clone stops the
219	/// worker.
220	pub type NotifySender = tokio::sync::mpsc::UnboundedSender<NotifyJob>;
221	
222	/// Spawn the worker that drains the queue against `client`.
223	///
224	/// Jobs run sequentially. That is intentional: the relay rate-limits per node, and the
225	/// volume here is device-count-scaled, not user-traffic-scaled. Sequential also means one
226	/// slow push delays the next rather than opening a connection storm at a struggling relay.
227	pub fn spawn_worker(
228	    client: Arc<NotifyRelayClient>,
229	    db: sqlx::SqlitePool,
230	) -> (NotifySender, tokio::task::JoinHandle<()>) {
231	    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<NotifyJob>();
232	    let handle = tokio::spawn(async move {
233	        while let Some(job) = rx.recv().await {
234	            if let Err(e) = run_job(&client, &db, job).await {
235	                // Every relay failure ends here. Notification delivery is best-effort by
236	                // design, so this is a log line, not an error path anyone recovers from.
237	                tracing::warn!(error = %e, "notify relay job failed");
238	            }
239	        }
240	        tracing::info!("notify relay worker stopped (queue closed)");
241	    });
242	    (tx, handle)
243	}
244	
245	async fn run_job(
246	    client: &NotifyRelayClient,
247	    db: &sqlx::SqlitePool,
248	    job: NotifyJob,
249	) -> anyhow::Result<()> {
250	    use crate::db::notifications as store;
251	    use notify_relay::protocol::PushOutcome;
252	
253	    match job {
254	        NotifyJob::RegisterHandle {
255	            owner,
256	            apns_token,
257	            apns_topic,
258	        } => {
259	            let response = client
260	                .call(Request::RegisterHandle {
261	                    apns_token,
262	                    apns_topic,
263	                })
264	                .await?;
265	            let Response::Handle { handle } = response else {
266	                anyhow::bail!("relay refused handle registration: {response:?}");
267	            };
268	            match &owner {
269	                RegistrationOwner::Account { did, device_uuid } => {
270	                    store::set_registration_handle(db, did, device_uuid, &handle).await?;
271	                }
272	                RegistrationOwner::AdminDevice { admin_device_id } => {
273	                    store::set_admin_registration_handle(db, admin_device_id, &handle).await?;
274	                }
275	            }
276	        }
277	        NotifyJob::DropHandle { handle } => {
278	            client.call(Request::DropHandle { handle }).await?;
279	        }
280	        NotifyJob::Push {
281	            owner,
282	            handle,
283	            kid,
284	            enc,
285	            ct,
286	        } => {
287	            let response = client
288	                .call(Request::Push {
289	                    handle,
290	                    // `kid` is a positive INTEGER PRIMARY KEY; the wire carries it as u32,
291	                    // which is the same value for every kid an instance will ever mint.
292	                    kid: kid as u32,
293	                    enc,
294	                    ct,
295	                    priority: None,
296	                    ttl_secs: None,
297	                    ping: None,
298	                })
299	                .await?;
300	            match response {
301	                Response::Pushed {
302	                    outcome: PushOutcome::Unregistered,
303	                } => {
304	                    // APNs 410, relayed back to us: this device token is permanently dead
305	                    // (app deleted, or reinstalled with a new token). Prune at the moment of
306	                    // proof — the alternative is fanning out to a corpse forever.
307	                    prune(db, &owner).await?;
308	                    tracing::info!("pruned a notification registration the relay reported dead");
309	                }
310	                Response::Pushed {
311	                    outcome: PushOutcome::Delivered,
312	                } => {}
313	                other => {
314	                    // Throttled, tooLarge, apnsError, unknownHandle — all real outcomes, none
315	                    // of them recoverable here. Log the shape and drop the banner.
316	                    tracing::warn!(?other, "notify relay declined a push");
317	                }
318	            }
319	        }
320	    }
321	    Ok(())
322	}
323	
324	async fn prune(db: &sqlx::SqlitePool, owner: &RegistrationOwner) -> Result<(), sqlx::Error> {
325	    use crate::db::notifications as store;
326	    match owner {
327	        RegistrationOwner::Account { did, device_uuid } => {
328	            store::delete_registration(db, did, device_uuid).await?;
329	        }
330	        RegistrationOwner::AdminDevice { admin_device_id } => {
331	            store::delete_admin_registration(db, admin_device_id).await?;
332	        }
333	    }
334	    Ok(())
335	}
