2	
3	//! Readable last-run state for the periodic background sweeps.
4	//!
5	//! The OTel gauges in `metrics.rs` are write-only from inside the process — only a
6	//! Prometheus scrape observes them. The operator health endpoint
7	//! (`GET /v1/admin/health`) reports the same "is the sweep alive" signal as JSON, so each
8	//! sweep records its completion here, in the same place it writes its gauges, and the
9	//! route reads it back. Unlike the gauges this works with `[telemetry] metrics_enabled`
10	//! off.
11	//!
12	//! The recording sites share the sweeps' failure posture: a failed pass records nothing,
13	//! so a stale (or absent) [`SweepRun`] is the operator's signal that passes are not
14	//! completing — never record unconditionally at loop top.
15	//!
16	//! A pass that *completes* while skipping some of its subjects is a different fault, and
17	//! staleness cannot express it: it records normally, with [`SweepRun::errors`] carrying the
18	//! count it could not do. Blob GC is the motivating case — it excludes accounts whose
19	//! reconcile failed rather than deleting blobs it could not prove were unreferenced.
20	
21	use std::sync::RwLock;
22	
23	/// One completed sweep pass.
24	#[derive(Debug, Clone, Copy)]
25	pub struct SweepRun {
26	    /// Unix seconds when the pass completed.
27	    pub completed_at: i64,
28	    /// Rows/files acted on by the pass (deleted blobs, pruned seq rows, reaped accounts,
29	    /// expired claim attempts).
30	    pub swept: u64,
31	    /// Failures the pass hit. A completed pass with `errors > 0` did run, but did not do its
32	    /// whole job — the distinction a stale `completed_at` alone cannot draw between "one
33	    /// subject is broken" and "the sweep is dead". Sweeps that have no per-item error path
34	    /// leave this `0`.
35	    ///
36	    /// This counts failed *operations*, not the work they cost. For blob GC one failed
37	    /// account is 1, however many of its blobs go uncollected as a result.
38	    pub errors: u64,
39	}
40	
41	impl SweepRun {
42	    /// A pass completing now, having swept `swept` items with no errors.
43	    pub fn now(swept: u64) -> Self {
44	        Self::now_with_errors(swept, 0)
45	    }
46	
47	    /// A pass completing now, having swept `swept` items and skipped `errors` on failures.
48	    pub fn now_with_errors(swept: u64, errors: u64) -> Self {
49	        Self {
50	            completed_at: chrono::Utc::now().timestamp(),
51	            swept,
52	            errors,
53	        }
54	    }
55	}
56	
57	/// Last completed pass per periodic sweep. Every field is `None` until that sweep's first
58	/// completed pass after boot (each first pass runs one full interval after startup).
59	#[derive(Debug, Default, Clone, Copy)]
60	pub struct SweepSnapshot {
61	    pub blob_gc: Option<SweepRun>,
62	    /// The blob mirror is a replicator rather than a reclaimer, but shares the sweep
63	    /// posture: `swept` counts bucket objects synced (uploads + deletes), and a stale
64	    /// pass is the alarm.
65	    pub blob_mirror: Option<SweepRun>,
66	    /// The blob scrub is a verifier rather than a reclaimer: `swept` counts integrity
67	    /// problems flagged this pass (missing files, hash/size mismatches, orphan files) that
68	    /// were not auto-healed — the operator alarm count. A stale pass is still the alarm.
69	    pub blob_scrub: Option<SweepRun>,
70	    pub firehose_gc: Option<SweepRun>,
71	    pub account_reaper: Option<SweepRun>,
72	    pub agent_claim_sweep: Option<SweepRun>,
73	    pub admin_nonce_sweep: Option<SweepRun>,
74	    /// The labeler watcher is a poller rather than a reclaimer, but shares the sweep
75	    /// posture: `swept` counts label rows changed, and a stale pass is the alarm.
76	    pub labeler_watch: Option<SweepRun>,
77	}
78	
79	/// Shared readable sweep state; one lives in `AppState` for the process lifetime.
80	#[derive(Debug, Default)]
81	pub struct SweepStatus {
82	    inner: RwLock<SweepSnapshot>,
83	}
84	
85	impl SweepStatus {
86	    pub fn record_blob_gc(&self, run: SweepRun) {
87	        self.write().blob_gc = Some(run);
88	    }
89	
90	    pub fn record_blob_mirror(&self, run: SweepRun) {
91	        self.write().blob_mirror = Some(run);
92	    }
93	
94	    pub fn record_blob_scrub(&self, run: SweepRun) {
95	        self.write().blob_scrub = Some(run);
96	    }
97	
98	    pub fn record_firehose_gc(&self, run: SweepRun) {
99	        self.write().firehose_gc = Some(run);
100	    }
101	
102	    pub fn record_account_reaper(&self, run: SweepRun) {
103	        self.write().account_reaper = Some(run);
104	    }
105	
106	    pub fn record_agent_claim_sweep(&self, run: SweepRun) {
107	        self.write().agent_claim_sweep = Some(run);
108	    }
109	
110	    pub fn record_admin_nonce_sweep(&self, run: SweepRun) {
111	        self.write().admin_nonce_sweep = Some(run);
112	    }
113	
114	    pub fn record_labeler_watch(&self, run: SweepRun) {
115	        self.write().labeler_watch = Some(run);
116	    }
117	
118	    pub fn snapshot(&self) -> SweepSnapshot {
119	        // A poisoned lock means a writer panicked mid-assignment of a Copy value — the
120	        // data cannot be torn, so read through the poison rather than propagating a panic
121	        // into the health endpoint.
122	        match self.inner.read() {
123	            Ok(guard) => *guard,
124	            Err(poisoned) => *poisoned.into_inner(),
125	        }
126	    }
127	
128	    fn write(&self) -> std::sync::RwLockWriteGuard<'_, SweepSnapshot> {
129	        match self.inner.write() {
130	            Ok(guard) => guard,
131	            Err(poisoned) => poisoned.into_inner(),
132	        }
133	    }
134	}
