136	#[cfg(test)]
137	mod tests {
138	    use super::*;
139	
140	    #[test]
141	    fn snapshot_starts_empty_and_reflects_recorded_runs() {
142	        let status = SweepStatus::default();
143	        let before = status.snapshot();
144	        assert!(before.blob_gc.is_none());
145	        assert!(before.firehose_gc.is_none());
146	        assert!(before.account_reaper.is_none());
147	        assert!(before.agent_claim_sweep.is_none());
148	        assert!(before.admin_nonce_sweep.is_none());
149	
150	        status.record_blob_gc(SweepRun {
151	            completed_at: 1000,
152	            swept: 3,
153	            errors: 0,
154	        });
155	        status.record_firehose_gc(SweepRun {
156	            completed_at: 2000,
157	            swept: 0,
158	            errors: 0,
159	        });
160	
161	        let after = status.snapshot();
162	        assert_eq!(after.blob_gc.unwrap().completed_at, 1000);
163	        assert_eq!(after.blob_gc.unwrap().swept, 3);
164	        assert_eq!(after.firehose_gc.unwrap().swept, 0);
165	        assert!(after.account_reaper.is_none());
166	    }
167	
168	    #[test]
169	    fn repeat_records_overwrite() {
170	        let status = SweepStatus::default();
171	        status.record_account_reaper(SweepRun {
172	            completed_at: 10,
173	            swept: 1,
174	            errors: 0,
175	        });
176	        status.record_account_reaper(SweepRun {
177	            completed_at: 20,
178	            swept: 0,
179	            errors: 0,
180	        });
181	        let snap = status.snapshot();
182	        assert_eq!(snap.account_reaper.unwrap().completed_at, 20);
183	        assert_eq!(snap.account_reaper.unwrap().swept, 0);
184	    }
185	}
